<?php
namespace App\Http\Controllers\HR;use App\Http\Controllers\Controller;use App\Models\{Employee,LeaveRequest,LeaveType};use Illuminate\Http\Request;class LeaveController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('hr.leave',['requests'=>LeaveRequest::with(['employee','type'])->where('property_id',$p)->latest()->paginate(25),'types'=>LeaveType::where('property_id',$p)->where('is_active',1)->get(),'employees'=>Employee::where('property_id',$p)->where('status','active')->get()]);}public function request(Request $r){$p=auth()->user()->property_id;$d=$r->validate(['employee_id'=>'required|integer','leave_type_id'=>'required|integer','start_date'=>'required|date','end_date'=>'required|date|after_or_equal:start_date','reason'=>'nullable|max:1000']);$d['property_id']=$p;$d['days']=(new \DateTime($d['start_date']))->diff(new \DateTime($d['end_date']))->days+1;LeaveRequest::create($d);return back()->with('success','Leave request submitted.');}public function decision(Request $r,LeaveRequest $leave){abort_unless($leave->property_id===auth()->user()->property_id,403);$d=$r->validate(['status'=>'required|in:approved,rejected','manager_notes'=>'nullable|max:1000']);$leave->update($d+['approved_by'=>auth()->id(),'approved_at'=>now()]);return back()->with('success','Leave request updated.');}}